  await until(() => cdp.eval("document.querySelectorAll('.cx-error').length === 1 && document.querySelector('.cx-error').textContent.includes('Chat Completions') && document.querySelector('#cx-activity').hidden"), "provider failure merged with actionable protocol hint");
