  await until(() => cdp.eval("CODEX.state.status.connection.mode === 'chatgpt' && !!CODEX.state.login"), "explicitly switch back to ChatGPT");
  assert.equal(fixture.codex.requests.filter(r => r.path === "/api/codex/login").length, loginCount + 1);
  await cdp.eval("document.querySelector('[data-act=login-cancel]').click()");
  await until(() => cdp.eval("!CODEX.state.login && !CODEX.state.setupBusy"), "cancel optional login");
  await cdp.call("Page.reload", {}); await until(() => cdp.eval("!!(window.__cc && window.CODEX && __cc.srv.connected)"), "skipped connection reload");

  await until(() => cdp.eval("!!CODEX.state.status && document.querySelector('#cx-onboarding').hidden"), "skip preference survives reload without account");
  assert.equal(fixture.codex.requests.filter(r => r.path === "/api/codex/login").length, loginCount + 1);
  ok("three connection choices, model discovery, protocol detection, connectivity errors/success, stale-result guard, draft preservation, busy guard and private keys");
  await cdp.eval("['cx.skipLogin','cx.onboarded','cx.thread'].forEach(k=>localStorage.removeItem(k))");
  await cdp.call("Page.navigate", { url: fixture.origin + "/test-blank" });
